-- Backup generated on 2026-10-25 20:34:09

CREATE OR REPLACE PROCEDURE public.sp_update_experience(IN p_id uuid, IN p_tenant_id uuid, IN p_title character varying, IN p_description text, IN p_status character varying, IN p_dna_payload jsonb, IN p_updated_at timestamp with time zone, IN p_version_id uuid, IN p_change_reason text, IN p_modified_by_user_id uuid)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_next_version INT; BEGIN     SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next_version     FROM experience_versions     WHERE experience_id = p_id;      UPDATE experiences     SET title = p_title,         description = p_description,         status = p_status,         dna_payload = p_dna_payload,         updated_at = p_updated_at     WHERE id = p_id AND tenant_id = p_tenant_id;      INSERT INTO experience_versions (id, experience_id, version_number, title, description, dna_payload, change_reason, modified_by_user_id, created_at)     VALUES (p_version_id, p_id, v_next_version, p_title, p_description, p_dna_payload, p_change_reason, p_modified_by_user_id, p_updated_at); END; $procedure$ ;
